// Met en forme la commande envoyée par le site (tout est offert)
const b = $input.first().json.body || {};

// Champ piège : seuls les robots le remplissent
if (b.website) throw new Error('Commande ignorée (anti-spam)');

const clean = (v, max = 300) => String(v ?? '').replace(/\s+/g, ' ').trim().slice(0, max);
const d = {
  orderId: clean(b.orderId, 30) || 'LQ-?',
  items: String(b.items ?? '').trim().slice(0, 2000),
  count: clean(b.count, 4),
  name: clean(b.name, 120),
  email: clean(b.email, 160),
  phone: clean(b.phone, 40),
  where: clean(b.where, 200),
  when: clean(b.when, 120) || 'Dès que possible',
  notes: String(b.notes ?? '').trim().slice(0, 1000),
  list: clean(b.list, 60) || 'Leclercq des étoiles',
};
if (!d.name || !d.where || !d.items) throw new Error('Commande incomplète');
if (d.email && !/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(d.email)) d.email = '';

const recu = new Date().toLocaleString('fr-FR', { timeZone: 'Europe/Paris', weekday: 'long', day: 'numeric', month: 'long', hour: '2-digit', minute: '2-digit' });

const subject = `[Commande ${d.orderId}] ${d.name} — ${d.where}`;
const text = [
  `Nouvelle commande reçue sur le site, ${recu}.`,
  '',
  `N° de commande : ${d.orderId}`,
  '',
  d.items,
  '',
  `Livrer à : ${d.where}`,
  `Quand     : ${d.when}`,
  `Qui       : ${d.name}`,
  `Téléphone : ${d.phone || '—'}`,
  `E-mail    : ${d.email || '—'}`,
  '',
  d.notes ? `Précisions :\n${d.notes}` : 'Pas de précisions.',
  '',
  "Répondez directement à ce mail pour écrire à l'étudiant.",
].join('\n');

const confirmSubject = `${d.list} — commande ${d.orderId} bien reçue`;
const confirmText = [
  `Bonjour ${d.name.split(' ')[0]},`,
  '',
  `Votre commande ${d.orderId} est bien arrivée :`,
  '',
  d.items,
  '',
  `Livraison : ${d.where} · ${d.when}`,
  '',
  "C'est offert par la liste ! Un membre vous livre très vite.",
  '',
  `La liste ${d.list}`,
].join('\n');

return [{ json: { ...d, subject, text, confirmSubject, confirmText } }];
